package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaTeDraft6 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_sharri_ma_amiltu" to DuaText("నా చెడు పనుల నుండి శరణాగతి", "ఓ అల్లాహ్, నేను చేసిన చెడు నుండి మరియు నేను చేయని చెడు నుండి నేను నీకు ఆశ్రయం కోరుతున్నాను.", "ఆయిషా (ర) ప్రకారం, ప్రవక్త సల్లల్లాహు అలైహి వసల్లం యొక్క దుఆ.", "ఏమి చేయబడిందో మరియు ఏమి రద్దు చేయబడిందో రెండింటి పర్యవసానాల నుండి రక్షణ."),
        "dua_jahdil_bala" to DuaText("తీవ్రమైన విచారణల నుండి శరణార్థులు", "ఓ అల్లాహ్, తీవ్రమైన విచారణ నుండి, కష్టాల నుండి, దుష్ట తీర్పు నుండి మరియు శత్రువుల మహిమ నుండి నేను నీలో ఆశ్రయం పొందుతున్నాను.", "తీవ్రమైన పరీక్షల నుండి, శత్రువుల ఉల్లాసాల నుండి శరణార్థిగా ఉండండి.", "ప్రవక్త సల్లల్లాహు అలైహి వసల్లం ఈ నాలుగు విషయాల నుండి ఆశ్రయం పొందారు."),
        "dua_fitnat_ghina_faqr" to DuaText("సంపద మరియు పేదరికం యొక్క పరీక్షల నుండి శరణార్థులు", "ఓ అల్లాహ్, సోమరితనం మరియు వృద్ధాప్యం నుండి, పాపం మరియు రుణం నుండి, సమాధి విచారణ మరియు శిక్ష నుండి, అగ్ని విచారణ మరియు శిక్ష నుండి, సంపద పరీక్ష యొక్క చెడు నుండి మరియు పేదరికం యొక్క పరీక్ష నుండి నేను నిన్ను ఆశ్రయిస్తున్నాను.", "సమాధి, నరకం, సంపద మరియు పేదరికం (దుఆలో భాగం) యొక్క పరీక్షల నుండి శరణార్థిగా ఉండండి.", "ప్రవక్త సల్లల్లాహు అలైహి వసల్లం నుండి సమగ్రమైన ఆశ్రయం."),
        "dua_kufr_faqr" to DuaText("అపనమ్మకం మరియు పేదరికం నుండి ఆశ్రయం", "ఓ అల్లాహ్, నేను అవిశ్వాసం మరియు పేదరికం నుండి నీలో ఆశ్రయం కోరుతున్నాను, మరియు సమాధి శిక్ష నుండి నేను నీలో ఆశ్రయం కోరుతున్నాను. నీవు తప్ప దేవుడు లేడు.", "మూడు సార్లు ఉదయం మరియు సాయంత్రం.", "అబూ బక్రా (ర) ప్రవక్త ఈ మాట విన్నారు."),
        "dua_sharri_sami" to DuaText("నా ఇంద్రియాల దుష్టత్వం నుండి శరణాగతి", "ఓ అల్లాహ్, నా వినికిడి చెడు, నా దృష్టి చెడు, నా నాలుక చెడు, నా హృదయ చెడు మరియు నా కోరిక చెడు నుండి నేను నిన్ను ఆశ్రయిస్తున్నాను.", "షకాల్ ఇబ్న్ హుమాయిద్ (ర.) కు బోధించారు.", "అవయవాలను మరియు తనను తాను పాపం నుండి రక్షించుకోవడానికి ఒక దుఆ."),
        "dua_hadm_gharaq" to DuaText("ఆకస్మిక మరణం మరియు ప్రమాదాల నుండి ఆశ్రయం", "ఓ అల్లాహ్, నేను (ఒక భవనం ద్వారా) నలిగిపోకుండా, ఎత్తు నుండి పడిపోకుండా, మునిగిపోవడం, మంటలు మరియు వృద్ధాప్యం నుండి, మరణ సమయంలో నన్ను దారి తప్పించే షైతాన్ నుండి, నీ మార్గం నుండి పారిపోతున్నప్పుడు చనిపోవడం నుండి మరియు (విషపూరిత) కుటుతో చనిపోవడం నుండి నిన్ను ఆశ్రయిస్తున్నాను.", "ప్రమాదాలు మరియు చెడు మరణం నుండి ఆశ్రయం పొందండి.", "ప్రవక్త నుండి ఆశ్రయం యొక్క దుఆ."),
        "dua_ju_khiyanah" to DuaText("ఆకలి మరియు ద్రోహం నుండి శరణార్ధులు", "ఓ అల్లాహ్, నేను ఆకలి నుండి నిన్ను ఆశ్రయిస్తున్నాను, ఎందుకంటే అది ఒక దుష్ట సహచరుడు, మరియు నేను మోసం నుండి నిన్ను ఆశ్రయిస్తున్నాను, ఎందుకంటే అది ఒక దుష్ట నమ్మకస్తుడు.", "ఆకలి మరియు ద్రోహం నుండి శరణాగతి.", "ప్రవక్త నుండి ఆశ్రయం యొక్క దుఆ."),
        "dua_huda_tuqa" to DuaText("మార్గదర్శకత్వం, భక్తి, పవిత్రత మరియు తగినంత", "ఓ అల్లాహ్, నేను నిన్ను మార్గనిర్దేశం, భక్తి, పవిత్రత మరియు స్వయం సమృద్ధి కోసం అడుగుతున్నాను.", "ప్రవక్త సల్లల్లాహు అలైహి వసల్లం యొక్క సంక్షిప్త, సమగ్ర దుఆ.", "మతం మరియు ఈ ప్రపంచం యొక్క నాలుగు పునాది ఆశీర్వాదాలు."),
        "dua_aslih_li_dini" to DuaText("నా మతాన్ని, ప్రపంచాన్ని, మరి తరువాతి ప్రపంచాన్ని సరిదిద్దుకోండి.", "ఓ అల్లాహ్, నా అన్ని వ్యవహారాలకు రక్షణగా నా మతాన్ని సరిచేయండి, నా ప్రాపంచిక జీవితాన్ని సరిచేయండి, దీనిలో నా జీవనోపాధి ఉంది, మరియు నా పరలోకాన్ని సరిచేయండి, దానికి నేను తిరిగి వస్తాను. ప్రతి మంచి విషయంలో నాకు జీవితాన్ని పెంచండి, మరియు ప్రతి చెడు నుండి మరణాన్ని నాకు ఉపశమనం కలిగించండి.", "మతం, ఈ ప్రపంచం మరియు పరలోకం-ఈ మూడింటినీ సంస్కరించడం.", "ప్రవక్త సల్లల్లాహు అలైహి వసల్లం యొక్క సమగ్ర దుఆ."),
        "dua_musarrifal_qulub" to DuaText("మా హృదయాలను మీ విధేయత వైపు మళ్లించండి", "ఓ అల్లాహ్, హృదయాలను మార్చిన వాడు, మా హృదయాలను నీ విధేయత వైపు మళ్లించు.", "విధేయతతో హృదయాన్ని దృఢంగా ఉంచడానికి ఒక దుఆ.", "ప్రజలందరి హృదయాలు పరమ కరుణామయుడి రెండు వేళ్ళ మధ్య ఉంటాయి."),
        "dua_jannah_nar" to DuaText("అగ్ని నుండి శరణు కోసం జన్నా అడగడం", "ఓ అల్లాహ్, నేను నిన్ను స్వర్గం కోసం అడుగుతున్నాను మరియు అగ్ని నుండి నిన్ను ఆశ్రయిస్తున్నాను.", "తాషాహ్హుద్ తర్వాత లేదా ఏ సమయంలోనైనా.", "ప్రవక్త సల్లల్లాహు అలైహి వసల్లం ఇలా అన్నారుః మన దుఆలు కూడా దీని చుట్టూ తిరుగుతాయి."),
        "dua_khayri_kullih" to DuaText("ఇప్పుడు మరియు తరువాత అంతా బాగుంది", "ఓ అల్లాహ్, నేను నిన్ను అన్ని మంచి కోసం అడుగుతున్నాను-తక్షణం మరియు ఆలస్యం, నాకు తెలిసినవి మరియు నాకు తెలియనివి-మరియు నేను అన్ని చెడుల నుండి-తక్షణం మరియు ఆలస్యం, నాకు తెలిసినవి మరియు నాకు తెలియనివి నుండి నిన్ను ఆశ్రయిస్తున్నాను. ఓ అల్లాహ్, నేను స్వర్గం కోసం అడుగుతున్నాను మరియు ఏ మాటలు మరియు పనులు నన్ను దానికి దగ్గర చేస్తాయో, మరియు నేను అగ్ని నుండి మరియు ఏ మాటలు మరియు పనుల నుండి నన్ను దానికి దగ్గర చేస్తానో దాని నుండి నిన్ను ఆశ్రయిస్తున్నాను.", "ప్రవక్త సల్లల్లాహు అలైహి వసల్లం ఈ సమగ్ర దుఆని ఆయిషా (రా) (దుఆలో భాగం) కు బోధించారు.", "ప్రతి మంచిని సేకరించే దుఆ."),
        "dua_ihdini_saddidni" to DuaText("నాకు మార్గనిర్దేశం చేయండి మరియు నన్ను సూటిగా ఉంచండి", "ఓ అల్లాహ్, నాకు మార్గనిర్దేశం చేసి, నన్ను సరైన మార్గంలో నడిపించండి.", "ప్రవక్త సల్లల్లాహు అలైహి వసల్లం అలీ (ర) కు ఈ విషయం బోధించారు.", "మార్గదర్శకత్వం అనేది రహదారిపై మార్గనిర్దేశం చేయబడుతుందని, సాదద్ అనేది బాణం యొక్క సరళత అని భావించండి."),
        "dua_hubbaka" to DuaText("అల్లాహ్ ప్రేమను అడగండి", "ఓ అల్లాహ్, నిన్ను ప్రేమించే వారి ప్రేమను, నన్ను నీ ప్రేమకు తీసుకువచ్చే పనులను నేను నిన్ను కోరుతున్నాను. ఓ అల్లాహ్, నీ ప్రేమను నాకంటే, నా కుటుంబం కంటే, చల్లటి నీళ్ళ కంటే నాకు ప్రియమైనదిగా చేయండి.", "దావూద్ (అ. స.) యొక్క దుఆ ప్రవక్త సల్లల్లాహు అలైహి వసల్లం ద్వారా సంబంధితమైనది.", "అల్లాహ్ ప్రేమ గొప్ప సంపద."),
        "dua_filal_khayrat" to DuaText("మంచి చేయడం మరియు చెడును వదిలివేయడం", "ఓ అల్లాహ్, మంచి పనులు చేయడానికి, చెడు పనులను వదిలి, పేదలను ప్రేమించడానికి, నన్ను క్షమించి, నాపై దయ చూపమని నేను నిన్ను అడుగుతున్నాను. మరియు మీరు ఒక ప్రజల కోసం విచారణను ఉద్దేశించినప్పుడు, నన్ను పరీక్షించకుండా తీసుకోండి. నేను నీ ప్రేమను, నిన్ను ప్రేమించే వారి ప్రేమను, నన్ను నీ ప్రేమకు దగ్గర చేసే పనుల ప్రేమను అడుగుతున్నాను.", "అల్లాహ్ ఈ దుఆ ప్రవక్తకు కలలో నేర్పించాడు.", "ప్రవక్త సల్లల్లాహు అలైహి వసల్లం ఇలా అన్నారుః ఇది నిజం, కాబట్టి దానిని నేర్చుకోండి మరియు బోధించండి."),
        "dua_bi_ilmikal_ghayb" to DuaText("జీవితం బాగున్నంత వరకు నన్ను జీవించనివ్వండి.", "ఓ అల్లాహ్, అదృశ్యమైన వాటి గురించి నీ జ్ఞానం మరియు సృష్టి మీద నీ శక్తి ద్వారా-నాకు జీవితం మంచిదని నీకు తెలిసినంత కాలం నన్ను సజీవంగా ఉంచండి, మరియు మరణం నాకు మంచిదని నీకు తెలిసినప్పుడు నన్ను తీసుకోండి. ఓ అల్లాహ్, ఏకాంతంగా మరియు బహిరంగంగా నీ గురించి భయపడమని, సంతృప్తి మరియు కోపంలో సత్యం యొక్క మాట కోసం, మరియు పేదరికం మరియు సంపదలో మితత్వం కోసం నేను నిన్ను అడుగుతున్నాను.", "అమ్మర్ ఇబ్న్ యాసిర్ (ఆర్ఏ) (ప్రారంభ భాగం) యొక్క ప్రార్థన దుఆ.", "ప్రవక్త సల్లల్లాహు అలైహి వసల్లం ప్రార్థనలో ఈ దుఆ చేశారు."),
        "dua_ism_azam_mannan" to DuaText("ఇస్మ్-ఎ-ఆజంః అల్-మన్నాన్", "ఓ అల్లాహ్, నేను నిన్ను అడుగుతున్నాను, ఎందుకంటే సమస్త స్తుతులు నీవే. నీవు తప్ప ఏ దేవుడు లేడు, అనుగ్రహం చేసేవాడు, ఆకాశాలు మరియు భూమిని సృష్టించేవాడు. ఓ మహిమ మరియు గౌరవం కలిగినవాడే, ఓ నిత్యజీవముగలవాడే, సంరక్షించేవాడే!", "ఈ వ్యక్తి అల్లాహ్ యొక్క గొప్ప పేరుతో దుఆ చేసాడని ప్రవక్త సల్లల్లాహు అలైహి వసల్లం అన్నారు.", "ఈ పేరుతో చేసిన దుఆకు సమాధానం ఇవ్వబడుతుంది."),
        "dua_ism_azam_ahad_samad" to DuaText("ఇస్మ్-ఎ-ఆజంః అల్-అహద్ అస్-సమద్", "ఓ అల్లాహ్, నేను నిన్ను అడుగుతున్నాను, ఎందుకంటే నీవు అల్లాహ్ అని నేను సాక్ష్యమిస్తున్నాను; నీవు తప్ప ఏ దేవుడు లేడు, ఒకడు, స్వయం సమృద్ధిగలవాడు, అతను జన్మించడు లేదా జన్మించడు, మరియు అతనితో పోల్చదగినవాడు లేడు.", "ఈ వ్యక్తి అల్లాహ్ ను తన గొప్ప పేరుతో అడిగాడని ప్రవక్త సల్లల్లాహు అలైహి వసల్లం అన్నారు.", "దాని ద్వారా అడిగినప్పుడు, అతను ఇస్తాడు; దాని ద్వారా పిలిచినప్పుడు, అతను సమాధానం ఇస్తాడు."),
        "dua_thabbitni_hadiyan" to DuaText("నన్ను దృఢంగా, మార్గనిర్దేశం చేయబడిన మరియు మార్గదర్శకురాలిగా చేయండి", "ఓ అల్లాహ్, నన్ను దృఢంగా ఉంచి, నన్ను మార్గనిర్దేశం చేసే, మార్గనిర్దేశం చేసే వ్యక్తిగా చేయండి.", "ప్రవక్త సల్లల్లాహు అలైహి వసల్లం ఈ దుఆని జరీర్ (ర) కోసం చేశారు (మీ కోసం'థాబిత్ని'అని చెప్పండి).", "జరీర్ (ఆర్ఏ) కు అసలు దుఆ'థాబిట్-హు'అనే పదాలను ఉపయోగిస్తుంది."),
        "dua_rabbighfir_tub_alayya" to DuaText("నన్ను క్షమించండి, నా పశ్చాత్తాపాన్ని అంగీకరించండి.", "నా ప్రభూ, నన్ను క్షమించి, నా పశ్చాత్తాపాన్ని అంగీకరించు. నిశ్చయంగా నీవు పశ్చాత్తాపానికి కారణమైనవాడవు, కరుణామయుడవు.", "ఒకే సమావేశంలో వంద సార్లు-ప్రవక్త సల్లల్లాహు అలైహి వసల్లం యొక్క అభ్యాసం.", "సహచరులు ప్రవక్త సల్లల్లాహు అలైహి వసల్లం ఒకే సమావేశంలో వంద సార్లు చెప్పినట్లు లెక్కించారు."),
        "dua_rafiq_ala" to DuaText("మరణిస్తున్న వ్యక్తి యొక్క దువా", "ఓ అల్లాహ్, నన్ను క్షమించు, నన్ను కరుణించు మరియు అత్యున్నత సహచరుడితో నాతో చేరు.", "ప్రవక్త యొక్క చివరి దుఆ-అనారోగ్యంతో ఉన్న వ్యక్తి తన కోసం చెప్పడానికి.", "ప్రవక్త సల్లల్లాహు అలైహి వసల్లం ఆయన మరణించిన సమయంలో ఈ దుఆ చేశారు."),
        "dua_la_bas_tahur" to DuaText("రోగులను ఓదార్చడంః శుద్దీకరణ", "హాని లేదు; అల్లాహ్ కోరుకుంటే అది (పాపాల నుండి) శుద్దీకరణ.", "సందర్శించినప్పుడు రోగులను ఓదార్చడానికి.", "రోగులను సందర్శించినప్పుడు ప్రవక్త సల్లల్లాహు అలైహి వసల్లం ఈ విషయం చెప్పారు."),
        "dua_talqeen" to DuaText("మరణిస్తున్న వారి కోసం తల్కీన్", "అల్లాహ్ తప్ప మరెవరికీ ఆరాధించబడే హక్కు లేదు.", "మరణిస్తున్న వ్యక్తి దగ్గర కలిమా పఠించండి (అలా చెప్పమని వారిని బలవంతం చేయవద్దు).", "'లా ఇలాహా ఇల్లల్లా'అనే చివరి పదాలు ఎవరికైనా స్వర్గంలోకి ప్రవేశిస్తాయి (అబూ దావూద్ 3116)."),
        "dua_ahyini_ma_kanat" to DuaText("మరణాన్ని కోరుకునే బదులు", "ఓ అల్లాహ్, నాకు జీవితం మంచిదైనంత కాలం నన్ను సజీవంగా ఉంచండి, మరియు మరణం నాకు మంచిదైనప్పుడు నన్ను తీసుకోండి.", "కష్టాల్లో మరణాన్ని కోరుకునే బదులు.", "ప్రవక్త సల్లల్లాహు అలైహి వసల్లం మరణాన్ని కోరుకోవడాన్ని నిషేధించి, బదులుగా దీనిని బోధించారు."),
        "dua_for_one_i_cursed" to DuaText("నేను పదాలతో బాధపడే వారి కోసం", "ఓ అల్లాహ్, నేను ఎవరిని అవమానించానో, వారిని పునరుత్థాన రోజున మీకు సన్నిహితంగా ఉండేలా చేయండి.", "మీరు కోపంగా చెడుగా మాట్లాడిన వ్యక్తి కోసం.", "ప్రవక్త సల్లల్లాహు అలైహి వసల్లం యొక్క ఒక దుఆ."),
        "dua_praising_someone" to DuaText("ఎవరినైనా స్తుతిస్తున్నప్పుడు", "నేను అలా భావిస్తాను, మరియు అల్లాహ్ అతని రెకనరర్, మరియు నేను అల్లాహ్ ముందు ఎవరి స్వచ్ఛతను ధృవీకరించను.", "అతిశయోక్తి చేయడానికి బదులు, ఎవరినైనా ప్రశంసించేటప్పుడు.", "ప్రవక్త సల్లల్లాహు అలైహి వసల్లం ఈ ప్రశంసాత్మక మర్యాదను బోధించారు."),
        "dua_being_praised" to DuaText("మీరు ప్రశంసించబడినప్పుడు", "ఓ అల్లాహ్, వారు చెప్పేదానికి నన్ను లెక్కలోకి తీసుకోకండి, మరియు వారికి తెలియనిదానికి నన్ను క్షమించండి.", "తనను తాను ప్రశంసించుకోవడం విన్నప్పుడు-సహచరుడి (ఆర్ఏ) అభ్యాసం.", "ప్రశంసించినప్పుడు అహంకారాన్ని నివారించడానికి ఒక మార్గం."),
        "dua_non_muslim_sneezes" to DuaText("ముస్లిమేతర వ్యక్తి తుమ్మినప్పుడు", "అల్లాహ్ మీకు మార్గనిర్దేశం చేసి, మీ వ్యవహారాలను సరిదిద్దుగాక.", "ఒక ముస్లిమేతర వ్యక్తి తుమ్ముతూ'అల్హమ్దులిల్లాహ్'అని చెప్పినప్పుడు.", "యూదులు ప్రవక్త'యార్హముకల్లా'అని చెప్పాలని ఆశిస్తూ ఆయన దగ్గర తుమ్ముతారు, ఆయన ఇలా చెబుతారు."),
        "dua_reply_ahl_kitab_salam" to DuaText("పుస్తకాల ప్రజల సలాంకు సమాధానం", "మరియు మీ మీద.", "గ్రంథస్తులు సలాం తో పలకరించినప్పుడు.", "ప్రవక్త సల్లల్లాహు అలైహి వసల్లం యొక్క బోధన."),
        "dua_fasting_invited" to DuaText("ఉపవాసం చేసేటప్పుడు ఆహ్వానించబడినప్పుడు", "నేను ఉపవాసం ఉంటాను.", "ఉపవాసం ఉన్నప్పుడు ఆహ్వానించబడినప్పుడు లేదా ఎవరైనా మీతో గొడవ పడినప్పుడు.", "ఉపవాసం ఉన్న వ్యక్తి ఆహ్వానాన్ని అంగీకరిస్తే, అతను అతిధేయుడి కోసం ప్రార్థించాలి."),
        "dua_for_who_gave_drink" to DuaText("నాకు తినిపించిన వారికోసం", "ఓ అల్లాహ్, నాకు తినిపించినవారికి తినిపించండి, నాకు తాగిన వారికి త్రాగండి.", "మీకు ఆహారం లేదా పానీయం ఇచ్చే వారికోసం.", "ప్రవక్త సల్లల్లాహు అలైహి వసల్లం అల్-మిక్దాద్ (ర) కోసం ఈ దుఆ చేశారు."),
        "dua_eid_greeting" to DuaText("ఈద్ శుభాకాంక్షలు", "అల్లాహ్ మా నుండి మరియు మీ నుండి (మంచి పనులను) అంగీకరించుగాక.", "ఈద్ రోజున ఒకరికొకరు-గొప్ప సహచరుల (ఆర్ఏ) ఆచారం.", "ఈద్ సందర్భంగా వారు కలిసినప్పుడు సహచరులు ఈ విషయం చెప్పారు."),
        "dua_wedding_night" to DuaText("నికాహ్ తర్వాత వధువు కోసం", "ఓ అల్లాహ్, మీరు ఆమెను సృష్టించిన ప్రకృతి యొక్క మంచి మరియు మంచిని నేను నిన్ను అడుగుతున్నాను, మరియు మీరు ఆమెను సృష్టించిన ప్రకృతి యొక్క చెడు నుండి మరియు చెడు నుండి నేను నిన్ను ఆశ్రయిస్తున్నాను.", "వివాహానంతరం, భార్య నుదిటిపై చేతిని ఉంచండి.", "ప్రవక్త యొక్క సలీం అల్లాహ్ వస్సం బోధన-వివాహంలో ఆశీర్వాదం."),
        "dua_istisqa_ibadak" to DuaText("మీ సేవకులకు, జంతువులకు నీరు అందించండి", "ఓ అల్లాహ్, నీ సేవకులకు, నీ జంతువులకు నీరు ఇవ్వు, నీ దయను వ్యాప్తి చేసి, నీ మృత భూమికి ప్రాణం పోసుకో.", "వర్షం కోసం అడగడం (ఇస్తిస్కా).", "ప్రవక్త సల్లల్లాహు అలైహి వసల్లం వర్షం కోసం ఈ దుఆ చేశారు."),
        "dua_seeing_clouds" to DuaText("చీకటి మేఘాలు చూడటం", "ఓ అల్లాహ్, దాని దుష్టత్వం నుండి నేను నీకు ఆశ్రయం కోరుతున్నాను.", "ఆకాశంలో చీకటి మేఘాలు చూసినప్పుడు, వర్షం పడితే,'అల్లాహుమ్మా సయ్యిబాన్ నఫియా'అని చెప్పండి.", "మేఘాలను చూసినప్పుడు, ప్రవక్త సల్లల్లాహు అలైహి వసల్లం తాను చేస్తున్న పనిని వదిలి ఈ దుఆ చేస్తారు."),
        "dua_jamarat" to DuaText("జమారాట్ మీద రాళ్లు రువ్వడం", "అల్లాహ్ గొప్పవాడు.", "ప్రతి గులకరాళ్ళతో విసిరారు.", "ప్రవక్త సల్లల్లాహు అలైహి వసల్లం ప్రతి గులకరాళ్ళతో తక్బీర్ అని చెప్పారు, తరువాత మొదటి మరియు రెండవ జమ్రా తరువాత కిబ్లాకు ఎదురుగా ఉండి పొడవైన దుఆ చేసారు."),
        "dua_rabbi_ainni" to DuaText("నా ప్రభూ, నాకు సహాయం చెయ్యి, నాకు వ్యతిరేకంగా కాదు.", "నా ప్రభూ, నాకు సహాయం చెయ్యి, నాకు వ్యతిరేకంగా ఇతరులకు సహాయం చేయవద్దు, నాకు విజయం ఇవ్వండి, నాపై ఇతరులకు విజయం ఇవ్వవద్దు, నా కోసం ప్రణాళిక వేసుకోండి, నాకు వ్యతిరేకంగా ప్రణాళిక వేయకండి, నాకు మార్గనిర్దేశం చేయండి, నాకు మార్గనిర్దేశం చేయండి, నాకు అన్యాయం చేసేవారిపై నాకు సహాయం చేయండి.", "ప్రవక్త సల్లల్లాహు అలైహి వసల్లం (ప్రారంభ భాగం) యొక్క సమగ్ర దుఆ.", "మతంలో మరియు ఈ ప్రపంచంలో ప్రతి సహాయాన్ని సేకరించే దుఆ."),
        "dua_ati_nafsi_taqwaha" to DuaText("నా ఆత్మకు దాని తక్వా ఇవ్వండి.", "ఓ అల్లాహ్, నా ఆత్మకు దాని ధర్మాన్ని ప్రసాదించి, దానిని శుద్ధి చేయి, ఎందుకంటే దానిని శుద్ధి చేయడంలో నీవే ఉత్తమమైనవాడు. నీవే దాని సంరక్షకుడు, దాని యజమాని.", "స్వీయాన్ని సంస్కరించడానికి మరియు శుద్ధి చేయడానికి.", "ప్రవక్త సల్లల్లాహు అలైహి వసల్లం ఈ దుఆ చేసేవారు."),
        "dua_iqsim_lana_khashyatik" to DuaText("మీ పట్ల మాకు అలాంటి భయాన్ని కలిగించండి.", "ఓ అల్లాహ్, మాకు మధ్యకు రావడానికి, నీకు అవిధేయత చూపడానికి నీ పట్ల మాకు తగినంత భయాన్ని కలిగించు, మమ్మల్ని నీ స్వర్గానికి తీసుకురావడానికి తగినంత విధేయత, ఈ ప్రపంచంలోని విపత్తులను మాకు సులభతరం చేయడానికి తగినంత ఖచ్చితత్వం ఇవ్వు. మీరు మమ్మల్ని సజీవంగా ఉంచినంత కాలం మా వినికిడిని, మా దృష్టిని, మా బలాన్ని ఆస్వాదించి, వాటిని మాకు శాశ్వతంగా చేస్కోండి. మాకు అన్యాయం చేసిన వారిపై మా ప్రతీకారం తీర్చుకోండి, మా శత్రువులపై మాకు సహాయం చేయండి, మా విపత్తు మా మతంలో ఉండనివ్వవద్దు, ఈ ప్రపంచాన్ని మా అతిపెద్ద ఆందోళనగా లేదా మా జ్ఞాన పరిమితిలా చేయవద్దు, మాకు దయ చూపని వారిని మాపై విధించవద్దు.", "ఒక సమూహం నుండి లేచినప్పుడు-ప్రవక్త సల్లల్లాహు అలైహి వసల్లం ఈ దుఆ చేయకుండా అరుదుగా లేచారు.", "మతం, ఈ ప్రపంచం మరియు పరలోకం యొక్క మంచి కోసం సమగ్ర దుఆ."),
        "dua_infani_bima_allamtani" to DuaText("మీరు నాకు నేర్పించిన దానితో నాకు ప్రయోజనం చేకూరండి.", "ఓ అల్లాహ్, నీవు నాకు నేర్పించిన దానితో నాకు ప్రయోజనం చేకూర్చుము, నాకు ప్రయోజనం కలిగించేది నాకు నేర్పుము, నాకు జ్ఞానాన్ని పెంచుము.", "జ్ఞానం కోసం వెతుకుతున్నప్పుడు లేదా అధ్యయనం చేసే ముందు.", "ప్రయోజనకరమైన జ్ఞానం మరియు దానిపై చర్య కోసం ఒక దుఆ."),
    )
}
